"""M8 drop points: migration 0007 and the seed generated by tools/convert/zones.py."""


def test_drop_points_seeded_from_upstream_zones(db):
    with db.cursor() as cur:
        cur.execute("SELECT COUNT(*) AS n, COUNT(DISTINCT zone) AS zones, SUM(used_at IS NULL) AS fresh FROM supply_drop_points")
        r = cur.fetchone()
        assert r["n"] == 36 and r["zones"] == 7 and r["fresh"] == 36  # upstream: 36 DefineSupplyDropPos over all zones
        cur.execute("SELECT name FROM supply_drop_points WHERE zone = 'bc' ORDER BY name")
        assert [x["name"] for x in cur.fetchall()] == ["Bone County Canyons", "Bone County East", "Fort Carson", "Verdant Meadows"]
        cur.execute("SELECT COUNT(*) AS n, MIN(zone) AS lo, MAX(zone) AS hi FROM weapon_cache_points")
        r = cur.fetchone()
        assert r["n"] == 186 and r["lo"] == "sf" and r["hi"] == "sf"  # upstream: 186 DefineWeaponsCachePos, all in sf.pwn


def test_drop_settings_seeded(db):
    with db.cursor() as cur:
        cur.execute("SELECT skey, svalue FROM settings WHERE skey LIKE 'loot.supply%' OR skey LIKE 'loot.cache%' OR skey = 'loot.drop_point_reuse_hours'")
        rows = {r["skey"]: r["svalue"] for r in cur.fetchall()}
        assert rows == {"loot.supply_tick_s": "60", "loot.supply_cooldown_s": "600", "loot.cache_interval_s": "1500",
                        "loot.cache_jitter_s": "600", "loot.cache_min_players": "4", "loot.drop_point_reuse_hours": "24"}


def test_house_loot_points_seeded_in_hollow_houses(db):
    with db.cursor() as cur:
        cur.execute("SELECT COUNT(*) AS n, COUNT(DISTINCT zone) AS zones FROM loot_spawns "
                    "WHERE table_name = 'world_civilian' AND size = 3 AND weight = 20 AND id > 11062")
        r = cur.fetchone()
        assert r["n"] > 50 and r["zones"] >= 1  # seed 0006: half of the 65 hollow houses (all SF today), 3-4 points each
        cur.execute("SELECT COUNT(*) AS n FROM loot_spawns s LEFT JOIN loot_spawn_state st ON st.spawn_id = s.id WHERE st.spawn_id IS NULL")
        assert cur.fetchone()["n"] == 0
